'use strict';

const http = require('node:http');
const crypto = require('node:crypto');

// Single-file NOVA AI — embedded frontend assets, no npm dependencies.
const bundled = Object.freeze({
  'index.html': Buffer.from('', 'base64'),
  'app.js': Buffer.from('', 'base64'),
  'style.css': Buffer.from('', 'base64'),
  'favicon.svg': Buffer.from('', 'base64')
});
const files = Object.freeze({
  '/': ['index.html', 'text/html; charset=utf-8'],
  '/index.html': ['index.html', 'text/html; charset=utf-8'],
  '/app.js': ['app.js', 'text/javascript; charset=utf-8'],
  '/style.css': ['style.css', 'text/css; charset=utf-8'],
  '/favicon.svg': ['favicon.svg', 'image/svg+xml'],
});
const models = new Set(['openai/gpt-oss-120b', 'openai/gpt-oss-20b', 'qwen/qwen3.8-27b']);
const geminiModels = new Set(['gemini-3.8-flash', 'gemini-3.5-flash-lite']);
const MAX_BODY = 96_000;
const MAX_MESSAGE = 12_000;
const MAX_MESSAGES = 28;
const SYSTEM_PROMPT = [
  'Senin adın Nova. Türkçe konuşan, bilgili, yaratıcı ve dürüst bir yapay zekâ asistanısın.',
  'Kullanıcı başka bir dil isterse o dilde yanıt ver.',
  'Kod, oyun geliştirme, öğrenme ve günlük sorularda uygulamalı, açık ve güvenilir yanıtlar üret.',
  'Bilmediğin veya erişimin olmayan bilgileri uydurma. Kod gerektiğinde kullanışlı örnekler sun.',
].join(' ');

function reply(res, code, body) {
  res.writeHead(code, {'Content-Type':'application/json; charset=utf-8', 'Cache-Control':'no-store'});
  res.end(JSON.stringify(body));
}
function safeEqual(a,b) {
  const aa = Buffer.from(a || ''); const bb = Buffer.from(b || '');
  return aa.length === bb.length && crypto.timingSafeEqual(aa,bb);
}
function makeServer(options = {}) {
  const apiKey = options.apiKey ?? process.env.GROQ_API_KEY ?? '';
  const geminiKey = options.geminiKey ?? process.env.GEMINI_API_KEY ?? '';
  const password = options.password ?? process.env.SITE_PASSWORD ?? '';
  const endpoint = options.endpoint ?? 'https://api.groq.com/openai/v1/chat/completions';
  const fetcher = options.fetcher ?? fetch;
  const geminiEndpoint = options.geminiEndpoint ?? 'https://generativelanguage.googleapis.com/v1beta/models';
  const rate = new Map();
  return http.createServer(async (req, res) => {
    res.setHeader('X-Content-Type-Options','nosniff');
    res.setHeader('Referrer-Policy','no-referrer');
    res.setHeader('X-Frame-Options','DENY');
    res.setHeader('Content-Security-Policy',"default-src 'self'; connect-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; font-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'");
    const pathname = new URL(req.url || '/', 'http://localhost').pathname;
    if (req.method === 'GET' && files[pathname]) {
      const [name, mime] = files[pathname];
      res.writeHead(200, {'Content-Type': mime, 'Cache-Control':'no-store'});
      res.end(bundled[name]);
      return;
    }
    if (req.method === 'GET' && pathname === '/api/status') {
      return reply(res, 200, {configured:Boolean(apiKey||geminiKey),groqConfigured:Boolean(apiKey),geminiConfigured:Boolean(geminiKey),passwordProtected:Boolean(password),models:[...models],geminiModels:[...geminiModels]});
    }
    if (req.method !== 'POST' || pathname !== '/api/chat') return reply(res, 404, {error:'Sayfa bulunamadı.'});
    if (!apiKey && !geminiKey) return reply(res, 503, {error:'Groq veya Gemini API anahtarı sunucuda ayarlanmamış. README dosyasını aç.'});
    if (password && !safeEqual(req.headers['x-nova-access'], password)) {
      return reply(res, 401, {error:'Site erişim şifresi yanlış. Ayarlar bölümünden doğru şifreyi gir.'});
    }
    const origin = req.headers.origin;
    if (origin) {
      try {
        if (new URL(origin).host !== req.headers.host) return reply(res,403,{error:'Bu siteden olmayan istek engellendi.'});
      } catch {return reply(res,403,{error:'Geçersiz istek kaynağı.'});}
    }
    if (!String(req.headers['content-type'] || '').startsWith('application/json')) return reply(res,415,{error:'JSON içeriği gerekli.'});
    const ip = req.socket.remoteAddress || 'unknown';
    const now = Date.now();
    const existing = (rate.get(ip) || []).filter(t => now - t < 60_000);
    if (existing.length >= 22) return reply(res,429,{error:'Bir dakikada çok fazla istek gönderildi. Biraz sonra dene.'});
    existing.push(now); rate.set(ip,existing);
    if (rate.size > 250) for (const [key, stamps] of rate) if (!stamps.some(t=>now-t<60_000)) rate.delete(key);

    let body;
    try {
      const data = []; let len = 0;
      for await (const chunk of req) {
        len += chunk.length;
        if (len > MAX_BODY) return reply(res,413,{error:'İstek çok uzun.'});
        data.push(chunk);
      }
      body = JSON.parse(Buffer.concat(data).toString('utf8'));
    } catch {return reply(res,400,{error:'Gönderilen veri okunamadı.'});}
    if (!body || !Array.isArray(body.messages) || body.messages.length < 1 || body.messages.length > MAX_MESSAGES ||
        !body.messages.every(m => m && (m.role === 'user' || m.role === 'assistant') && typeof m.content === 'string' && m.content.trim() && m.content.length <= MAX_MESSAGE) ||
        body.messages.at(-1).role !== 'user') return reply(res,400,{error:'Mesaj biçimi geçersiz.'});
    const rawChoice = typeof body.model === 'string' ? body.model : 'duo';
    const mode = rawChoice === 'duo' ? 'duo' : rawChoice === 'gemini' || rawChoice.startsWith('gemini:') ? 'gemini' : 'groq';
    const requestedGroq = rawChoice.startsWith('groq:') ? rawChoice.slice(5) : rawChoice;
    const requestedGemini = rawChoice.startsWith('gemini:') ? rawChoice.slice(7) : rawChoice;
    const model = models.has(requestedGroq) ? requestedGroq : 'openai/gpt-oss-120b';
    const geminiModel = geminiModels.has(requestedGemini) ? requestedGemini : 'gemini-3.8-flash';
    if (mode === 'groq' && !apiKey) return reply(res,503,{error:'Groq API anahtarı sunucuda ayarlanmamış.'});
    if (mode === 'gemini' && !geminiKey) return reply(res,503,{error:'Gemini API anahtarı sunucuda ayarlanmamış.'});
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 90_000);
    res.on('close', () => {if (!res.writableFinished) controller.abort();});
    async function groqOnce() {
      if (!apiKey) throw new Error('Groq anahtarı ayarlanmamış.');
      const r = await fetcher(endpoint, {
        method:'POST',signal:controller.signal,
        headers:{'Authorization':`Bearer ${apiKey}`,'Content-Type':'application/json'},
        body:JSON.stringify({model, messages:[{role:'system',content:SYSTEM_PROMPT},...body.messages],stream:false,temperature:0.7,max_completion_tokens:4096}),
      });
      if (!r.ok) throw new Error(r.status===401||r.status===403?'Groq: Anahtar geçersiz veya yetkisiz.':r.status===429?'Groq: Kullanım limiti doldu.':r.status===404?'Groq: Model mevcut değil.':`Groq: Sunucu hatası (${r.status}).`);
      const data=await r.json();
      const answer=data?.choices?.[0]?.message?.content;
      if(typeof answer!=='string'||!answer.trim()) throw new Error('Groq boş cevap gönderdi.');
      return answer;
    }
    async function geminiOnce() {
      if (!geminiKey) throw new Error('Gemini anahtarı ayarlanmamış.');
      const contents=body.messages.map(m=>({role:m.role==='assistant'?'model':'user',parts:[{text:m.content}]}));
      const r=await fetcher(`${geminiEndpoint}/${geminiModel}:generateContent`,{
        method:'POST',signal:controller.signal,
        headers:{'x-goog-api-key':geminiKey,'x-goog-api-client':'nova-ai-duo/3.0','Content-Type':'application/json'},
        body:JSON.stringify({systemInstruction:{parts:[{text:SYSTEM_PROMPT}]},contents,generationConfig:{temperature:0.7,maxOutputTokens:4096}}),
      });
      if(!r.ok) throw new Error(r.status===401||r.status===403?'Gemini: Anahtar geçersiz veya yetkisiz (AQ. anahtarlarında doğrulama sorunu yaşanabilir).':r.status===429?'Gemini: Kullanım limiti doldu.':r.status===404?'Gemini: Model hesabında mevcut değil.':`Gemini: Sunucu hatası (${r.status}).`);
      const data=await r.json();
      const answer=(data?.candidates?.[0]?.content?.parts||[]).filter(part=>typeof part.text==='string'&&!part.thought).map(part=>part.text).join('');
      if(!answer.trim()) throw new Error('Gemini yanıt üretmedi (güvenlik filtresi veya model kısıtlaması).');
      return answer;
    }
    try {
      if(mode==='duo'||mode==='gemini') {
        // Promise.allSettled starts both providers immediately; a failing provider never hides the other's answer.
        const results=await Promise.allSettled(mode==='duo'?[groqOnce(),geminiOnce()]:[geminiOnce()]);
        const blocks=[];const errors=[];
        for(let i=0;i<results.length;i++) {
          const provider=mode==='duo'?(i===0?'Groq':'Gemini'):'Gemini';
          const item=results[i];
          if(item.status==='fulfilled') blocks.push(`### ${provider} cevabı\n\n${item.value}`);
          else errors.push(item.reason?.message||`${provider} bağlantısı başarısız.`);
        }
        if(!blocks.length) return reply(res,502,{error:errors.join(' / ')});
        if(errors.length) blocks.push('### Bağlantı uyarısı\n\n'+errors.join('\n\n'));
        const content=blocks.join('\n\n');
        res.writeHead(200,{'Content-Type':'application/x-ndjson; charset=utf-8','Cache-Control':'no-cache, no-transform'});
        res.write(JSON.stringify({type:'delta',text:content})+'\n');
        res.end(JSON.stringify({type:'done'})+'\n');
        return;
      }
      const upstream = await fetcher(endpoint, {
        method:'POST', signal: controller.signal,
        headers: {'Authorization':`Bearer ${apiKey}`, 'Content-Type':'application/json'},
        body: JSON.stringify({model, messages:[{role:'system',content:SYSTEM_PROMPT},...body.messages], stream:true, temperature:0.7, max_completion_tokens:4096}),
      });
      if (!upstream.ok) {
        const data = await upstream.json().catch(()=>({}));
        const error = upstream.status===401?'Groq API anahtarı geçersiz veya süresi dolmuş.':
          upstream.status===429?'Groq kullanım limitine ulaşıldı.':
          upstream.status===404?'Seçilen Groq modeli hesabında bulunamadı; diğer modeli dene.':
          String(data?.error?.message || 'Groq bağlantısı başarısız.').slice(0,250);
        return reply(res,upstream.status===429?429:502,{error});
      }
      if (!upstream.body) return reply(res,502,{error:'Groq yanıt akışı bulunamadı.'});
      res.writeHead(200, {'Content-Type':'application/x-ndjson; charset=utf-8', 'Cache-Control':'no-cache, no-transform', 'X-Accel-Buffering':'no'});
      const reader = upstream.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let ended = false;
      function parseLine(line) {
        const trimmed = line.trim();
        if (!trimmed.startsWith('data:')) return;
        const payload = trimmed.slice(5).trim();
        if (payload === '[DONE]') {ended = true; return;}
        try {
          const chunk = JSON.parse(payload);
          const delta = chunk?.choices?.[0]?.delta?.content;
          if (typeof delta === 'string' && delta) res.write(JSON.stringify({type:'delta',text:delta})+'\n');
          if (chunk.error) res.write(JSON.stringify({type:'error',error:String(chunk.error.message||'Groq akış hatası.')})+'\n');
        } catch {}
      }
      while (!ended) {
        const {value,done} = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, {stream:true});
        let pos;
        while ((pos=buffer.indexOf('\n')) !== -1) {
          const line = buffer.slice(0,pos); buffer = buffer.slice(pos+1);
          parseLine(line);
          if (ended) break;
        }
      }
      if (buffer) parseLine(buffer);
      res.write(JSON.stringify({type:'done'})+'\n');
      res.end();
      try {await reader.cancel();} catch {}
    } catch(err) {
      const msg = err?.name === 'AbortError' ? 'Yanıt süresi doldu veya işlem durduruldu.' : 'Yapay zekâ sunucusuna bağlanılamadı.';
      if (res.headersSent) {if (!res.writableEnded) res.end(JSON.stringify({type:'error',error:msg})+'\n');}
      else reply(res, 502, {error:msg});
    } finally {clearTimeout(timer);}
  });
}

if (require.main === module) {
  const port = Number(process.env.PORT || 3000);
  const host = process.env.HOST || '0.0.0.0';
  makeServer().listen(port,host,()=>console.log(`NOVA AI hazır → http://${host}:${port}`));
}
module.exports = {makeServer};